package org.breatheless.app
import android.content.*
import android.database.*
import android.graphics.*
import android.net.Uri
import android.os.ParcelFileDescriptor
import android.provider.OpenableColumns
import java.io.*
import java.text.SimpleDateFormat
import java.util.*

object Exports{
    fun trimCache(c:Context){val files=File(c.cacheDir,"exports").listFiles()?.filter{it.isFile} ?:return;val now=System.currentTimeMillis();files.filter{now-it.lastModified()>7*86400000L}.forEach{it.delete()};var bytes=files.filter{it.exists()}.sumOf{it.length()};for(f in files.sortedBy{it.lastModified()})if(f.exists() && bytes>128*1024*1024 && now-f.lastModified()>3600000){val n=f.length();if(f.delete())bytes-=n}}
    fun csv(entries:List<Entry>):String{val date=SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ssXXX",Locale.US);val out=StringBuilder("\uFEFF");fun row(v:List<String>){out.append(v.joinToString(","){Analysis.csv(it)}).append("\r\n")};row(listOf("Entry ID","Date and time","Title","Status","Context","Duration seconds","Valid CP seconds","Excluded CP seconds","CP details (seconds | validity | date | label)","Pulse (bpm | date | label)","Walking (steps | seconds | source)","Symptom score (0 none - 10 worst)","Notes"));entries.sortedBy{it.timestamp}.forEach{e->row(listOf(e.id,date.format(Date(e.timestamp)),e.name,e.status,e.context,e.duration.toString(),e.cps.filter{it.valid}.joinToString("; "){"%.1f".format(Locale.US,it.seconds)},e.cps.filter{!it.valid}.joinToString("; "){"%.1f".format(Locale.US,it.seconds)},e.cps.joinToString("; "){"${"%.1f".format(Locale.US,it.seconds)} | ${if(it.valid)"valid"else"excluded"} | ${date.format(Date(it.timestamp))} | ${it.label}"},e.pulses.joinToString("; "){"${it.bpm} | ${date.format(Date(it.timestamp))} | ${it.label}"},e.walks.joinToString("; "){"${it.steps} | ${"%.1f".format(Locale.US,it.seconds)} | ${it.source}"},e.symptom?.toString() ?:"",e.comment))};return out.toString()}
    fun file(c:Context,name:String,bytes:ByteArray):File{trimCache(c);return File(File(c.cacheDir,"exports").apply{mkdirs()},name).apply{writeBytes(bytes)}}
    fun images(c:Context,entries:List<Entry>):List<File>{trimCache(c);val folder=File(c.cacheDir,"exports").apply{mkdirs()};val token=System.currentTimeMillis();val files=mutableListOf<File>();val p=Paint(Paint.ANTI_ALIAS_FLAG);val date=SimpleDateFormat("d MMM yyyy · HH:mm z",Locale.getDefault());var bmp:Bitmap?=null;var canvas:Canvas?=null;var y=0f;var page=0
        fun begin(){check(page<200){"The image export exceeds 200 pages. Export the full CSV table instead."};page++;bmp=Bitmap.createBitmap(1080,1600,Bitmap.Config.ARGB_8888);canvas=Canvas(bmp!!);canvas!!.drawColor(Color.BLACK);p.typeface=Typeface.create("sans-serif-medium",0);p.color=P.text;p.textSize=46f;canvas!!.drawText("Upekkhā diary",60f,85f,p);p.typeface=Typeface.create("sans-serif",0);p.textSize=21f;p.color=P.muted;canvas!!.drawText("${entries.size} entries · page $page",60f,129f,p);p.textSize=18f;canvas!!.drawText("CP is a personal observation; excluded values are marked.",60f,164f,p);p.color=P.line;canvas!!.drawLine(60f,186f,1020f,186f,p);y=226f}
        fun flush(){p.color=P.muted;p.textSize=18f;canvas!!.drawText("Exported ${date.format(Date())}",60f,1554f,p);val f=File(folder,"Upekkha-diary-$token-$page.png");f.outputStream().use{check(bmp!!.compress(Bitmap.CompressFormat.PNG,100,it))};files.add(f);bmp!!.recycle();bmp=null}
        fun line(t:String,bold:Boolean=false){p.textSize=if(bold)28f else 23f;p.typeface=Typeface.create("sans-serif",if(bold)1 else 0);p.color=if(bold)P.text else P.muted;for(part in t.split('\n')){var remaining=part;if(part.isEmpty())y+=16;while(remaining.isNotEmpty()){if(y>1488){flush();begin();p.textSize=if(bold)28f else 23f;p.typeface=Typeface.create("sans-serif",if(bold)1 else 0);p.color=if(bold)P.text else P.muted};val n=p.breakText(remaining,true,960f,null).coerceAtLeast(1);canvas!!.drawText(remaining.take(n),60f,y,p);remaining=remaining.drop(n);y+=34}}}
        try{begin();entries.sortedByDescending{it.timestamp}.forEachIndexed{i,e->if(y>1280){flush();begin()};line("${i+1}. ${e.name}",true);line(date.format(Date(e.timestamp))+" · "+e.context);line("${e.status} · ${e.duration/60}m ${e.duration%60}s");e.cps.forEach{line("${it.label}: ${"%.1f".format(it.seconds)} s · ${if(it.valid)"VALID"else"EXCLUDED"} · ${date.format(Date(it.timestamp))}")};e.pulses.forEach{line("Pulse: ${it.bpm} bpm · ${it.label} · ${date.format(Date(it.timestamp))}")};e.walks.forEachIndexed{n,w->line("Walking ${n+1}: ${w.steps} steps · ${"%.1f".format(w.seconds)} s · ${w.source}")};line("Symptoms: ${e.symptom?.let{"$it / 10 (higher = worse)"} ?:"not recorded"}");if(e.comment.isNotBlank())line("Notes: ${e.comment}");y+=24};flush();return files}catch(e:Exception){bmp?.recycle();files.forEach{it.delete()};throw e}
    }
}
class ExportProvider:ContentProvider(){override fun onCreate()=true
    private fun resolve(u:Uri):File{val n=u.lastPathSegment ?:throw FileNotFoundException();if(u.authority!="org.breatheless.app.exports" || u.pathSegments.size!=1 || !n.matches(Regex("[A-Za-z0-9._-]+")) || n=="." || n=="..")throw FileNotFoundException();val parent=File(context!!.cacheDir,"exports").canonicalFile;val f=File(parent,n).canonicalFile;if(f.parentFile!=parent || !f.isFile)throw FileNotFoundException();return f}
    override fun getType(u:Uri)=when(resolve(u).extension){"png"->"image/png";"csv"->"text/csv";else->"application/octet-stream"}
    override fun openFile(u:Uri,mode:String):ParcelFileDescriptor{if(mode!="r")throw SecurityException("Read-only export");return ParcelFileDescriptor.open(resolve(u),ParcelFileDescriptor.MODE_READ_ONLY)}
    override fun query(u:Uri,projection:Array<out String>?,selection:String?,args:Array<out String>?,sort:String?):Cursor{val f=resolve(u);val cols=projection ?:arrayOf(OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE);return MatrixCursor(cols).apply{addRow(cols.map{when(it){OpenableColumns.DISPLAY_NAME->f.name;OpenableColumns.SIZE->f.length();else->null}})}}
    override fun insert(u:Uri,v:ContentValues?):Uri?=throw UnsupportedOperationException();override fun delete(u:Uri,s:String?,a:Array<out String>?):Int=throw UnsupportedOperationException();override fun update(u:Uri,v:ContentValues?,s:String?,a:Array<out String>?):Int=throw UnsupportedOperationException()
    companion object{fun uri(name:String)=Uri.Builder().scheme("content").authority("org.breatheless.app.exports").appendPath(name).build()}
}
